const air = (x, y, z) => g.isAir(x, y, z);
const floor = (x, y, z) => !air(x, y, z);
const ok = (x, z) => air(x, 5, z) && air(x, 6, z) && floor(x, 4, z) || (g.blockAt(x, 5, z).includes("stairs") && air(x, 6, z) && floor(x, 4, z));
const start = [3, 7], seen = new Set([start.join()]), q = [start];
while (q.length) {
  const [x, z] = q.shift();
  for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
    const nx = x + dx, nz = z + dz, k = `${nx},${nz}`;
    if (seen.has(k) || nx < 1 || nx > 8 || nz < 4 || nz > 8 || !ok(nx, nz)) continue;
